#!/usr/bin/env node
/**
 * Generates `src/types/database.ts` by introspecting a live PostgreSQL
 * database, so the TypeScript types can never drift from the migrations.
 *
 *   DATABASE_URL=postgres://... node scripts/generate-db-types.mjs
 *
 * Uses `psql` rather than a driver dependency: the file is regenerated by
 * hand or in CI, never at build time.
 */
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const DATABASE_URL = process.env.DATABASE_URL;

if (!DATABASE_URL) {
  console.error('DATABASE_URL is required. Point it at a database with the migrations applied.');
  process.exit(2);
}

const query = (sql) =>
  JSON.parse(
    execFileSync('psql', [DATABASE_URL, '-tAX', '-c', `select coalesce(json_agg(t), '[]') from (${sql}) t`], {
      encoding: 'utf8',
      maxBuffer: 32 * 1024 * 1024,
    }).trim(),
  );

const enums = query(`
  select t.typname as name, array_agg(e.enumlabel order by e.enumsortorder) as values
  from pg_type t
  join pg_enum e on e.enumtypid = t.oid
  join pg_namespace n on n.oid = t.typnamespace
  where n.nspname = 'public'
  group by t.typname
  order by t.typname
`);

const columns = query(`
  select c.relname as table_name,
         a.attname as column_name,
         format_type(a.atttypid, a.atttypmod) as formatted_type,
         t.typname as udt_name,
         not a.attnotnull as is_nullable,
         (a.atthasdef or a.attidentity <> '') as has_default,
         a.attidentity <> '' as is_identity,
         a.attnum as ordinal
  from pg_attribute a
  join pg_class c on c.oid = a.attrelid
  join pg_namespace n on n.oid = c.relnamespace
  join pg_type t on t.oid = a.atttypid
  where n.nspname = 'public' and c.relkind in ('r','v','m') and a.attnum > 0 and not a.attisdropped
  order by c.relname, a.attnum
`);


const relationships = query(`
  select c.conname as name,
         src.relname as table_name,
         tgt.relname as referenced_relation,
         (select array_agg(a.attname order by k.ord)
            from unnest(c.conkey) with ordinality as k(attnum, ord)
            join pg_attribute a on a.attrelid = c.conrelid and a.attnum = k.attnum) as columns,
         (select array_agg(a.attname order by k.ord)
            from unnest(c.confkey) with ordinality as k(attnum, ord)
            join pg_attribute a on a.attrelid = c.confrelid and a.attnum = k.attnum) as referenced_columns,
         exists (
           select 1 from pg_index i
           where i.indrelid = c.conrelid and i.indisunique
             and i.indnatts = array_length(c.conkey, 1)
             and i.indkey::int2[] @> c.conkey and c.conkey @> i.indkey::int2[]
         ) as is_one_to_one
  from pg_constraint c
  join pg_class src on src.oid = c.conrelid
  join pg_class tgt on tgt.oid = c.confrelid
  join pg_namespace n on n.oid = src.relnamespace
  where c.contype = 'f' and n.nspname = 'public'
  order by src.relname, c.conname
`);

const relsByTable = new Map();
for (const rel of relationships) {
  if (!relsByTable.has(rel.table_name)) relsByTable.set(rel.table_name, []);
  relsByTable.get(rel.table_name).push(rel);
}

const enumNames = new Set(enums.map((e) => e.name));

function tsType(col) {
  const udt = col.udt_name;
  if (enumNames.has(udt)) return pascal(udt);
  if (udt.startsWith('_')) {
    const inner = udt.slice(1);
    return `${enumNames.has(inner) ? pascal(inner) : scalar(inner)}[]`;
  }
  return scalar(udt);
}

function scalar(udt) {
  switch (udt) {
    case 'bool':
      return 'boolean';
    case 'int2':
    case 'int4':
    case 'int8':
    case 'float4':
    case 'float8':
    case 'numeric':
      return 'number';
    case 'json':
    case 'jsonb':
      return 'Json';
    default:
      return 'string';
  }
}

const pascal = (s) => s.split('_').map((p) => p.charAt(0).toUpperCase() + p.slice(1)).join('');

const byTable = new Map();
for (const col of columns) {
  if (!byTable.has(col.table_name)) byTable.set(col.table_name, []);
  byTable.get(col.table_name).push(col);
}

const lines = [];
lines.push('/**');
lines.push(' * GENERATED FILE - do not edit by hand.');
lines.push(' *');
lines.push(' * Regenerate after changing a migration:');
lines.push(' *   DATABASE_URL=postgres://... node scripts/generate-db-types.mjs');
lines.push(' */');
lines.push('');
lines.push('export type Json = string | number | boolean | null | { [key: string]: Json | undefined } | Json[];');
lines.push('');

for (const e of enums) {
  lines.push(`export type ${pascal(e.name)} = ${e.values.map((v) => `'${v}'`).join(' | ')};`);
}
lines.push('');

lines.push('export interface Database {');
lines.push("  __InternalSupabase: { PostgrestVersion: '13' };");
lines.push('  public: {');
lines.push('    Tables: {');
for (const [table, cols] of [...byTable.entries()].sort()) {
  lines.push(`      ${table}: {`);
  lines.push('        Row: {');
  for (const c of cols) {
    lines.push(`          ${c.column_name}: ${tsType(c)}${c.is_nullable ? ' | null' : ''};`);
  }
  lines.push('        };');
  lines.push('        Insert: {');
  for (const c of cols) {
    const optional = c.is_nullable || c.has_default;
    lines.push(`          ${c.column_name}${optional ? '?' : ''}: ${tsType(c)}${c.is_nullable ? ' | null' : ''};`);
  }
  lines.push('        };');
  lines.push('        Update: {');
  for (const c of cols) {
    lines.push(`          ${c.column_name}?: ${tsType(c)}${c.is_nullable ? ' | null' : ''};`);
  }
  lines.push('        };');
  lines.push('        Relationships: [');
  for (const rel of relsByTable.get(table) ?? []) {
    lines.push(
      `          { foreignKeyName: '${rel.name}'; columns: [${rel.columns.map((c) => `'${c}'`).join(', ')}]; isOneToOne: ${rel.is_one_to_one}; referencedRelation: '${rel.referenced_relation}'; referencedColumns: [${rel.referenced_columns.map((c) => `'${c}'`).join(', ')}] },`,
    );
  }
  lines.push('        ];');
  lines.push('      };');
}
lines.push('    };');
lines.push('    Views: Record<string, never>;');
lines.push('    Functions: {');
lines.push('      is_admin: { Args: { p_user_id?: string }; Returns: boolean };');
lines.push('      is_staff: { Args: { p_user_id?: string }; Returns: boolean };');
lines.push('      owns_story: { Args: { p_story_id: string; p_user_id?: string }; Returns: boolean };');
lines.push('      get_shared_story: { Args: { p_token: string }; Returns: Json };');
lines.push('      touch_share_link: { Args: { p_token: string }; Returns: undefined };');
lines.push('      admin_dashboard_metrics: { Args: { p_days?: number }; Returns: Json };');
lines.push('      request_account_deletion: { Args: Record<string, never>; Returns: undefined };');
lines.push('      next_order_number: { Args: Record<string, never>; Returns: string };');
lines.push('      record_credit_transaction: {');
lines.push('        Args: {');
lines.push('          p_owner_id: string;');
lines.push('          p_delta: number;');
lines.push('          p_reason: CreditReason;');
lines.push('          p_idempotency_key?: string | null;');
lines.push('          p_story_id?: string | null;');
lines.push('          p_job_id?: string | null;');
lines.push('          p_note?: string | null;');
lines.push('          p_metadata?: Json;');
lines.push('        };');
lines.push('        Returns: number;');
lines.push('      };');
lines.push('      claim_generation_jobs: {');
lines.push('        Args: { p_limit?: number; p_worker?: string; p_types?: JobType[] | null };');
lines.push("        Returns: Database['public']['Tables']['generation_jobs']['Row'][];");
lines.push('      };');
lines.push('      reap_stalled_jobs: { Args: { p_stale_after?: string }; Returns: number };');
lines.push('      consume_rate_limit: {');
lines.push('        Args: { p_bucket: string; p_subject: string; p_limit: number; p_window_seconds: number };');
lines.push('        Returns: number;');
lines.push('      };');
lines.push('    };');
lines.push('    Enums: {');
for (const e of enums) {
  lines.push(`      ${e.name}: ${pascal(e.name)};`);
}
lines.push('    };');
lines.push('    CompositeTypes: Record<string, never>;');
lines.push('  };');
lines.push('}');
lines.push('');
lines.push("export type Tables<T extends keyof Database['public']['Tables']> =");
lines.push("  Database['public']['Tables'][T]['Row'];");
lines.push("export type TablesInsert<T extends keyof Database['public']['Tables']> =");
lines.push("  Database['public']['Tables'][T]['Insert'];");
lines.push("export type TablesUpdate<T extends keyof Database['public']['Tables']> =");
lines.push("  Database['public']['Tables'][T]['Update'];");
lines.push('');

writeFileSync(join(ROOT, 'src/types/database.ts'), lines.join('\n'));
console.log(`Wrote src/types/database.ts (${byTable.size} tables, ${enums.length} enums)`);
